import static org.junit.Assert.assertNull;

public class TestProtocol {
    private String message = "Hello";

    public void testGetMessage() {
        Protocol protocol = new Protocol();
        assertNotNull(protocol.getMessage());
        assertNull(protocol.getException());

        // Test with a valid message
        assertEquals("Hello", protocol.getMessage());

        // Test with an invalid message
        try {
            protocol.getMessage();
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            pass(); // Expected exception
        }
    }

    public void testGetMessageWithException() {
        Protocol protocol = new Protocol();
        assertNull(protocol.getMessage());
        assertEquals("", protocol.getException());
    }

    private class Protocol {
        String getMessage() {
            return message;
        }

        Object getException() {
            return null;
        }
    }
}
